def vector_records():
    return {digest(json.loads(raw)):Record(raw.encode()) for ident,_,_,raw in GOLDENS if ident!='V030'} | {digest(json.loads(CORRECTED)):Record(CORRECTED.encode())}


def record(kind):
    return next(r for r in vector_records().values() if r.value['kind']=='PURE.'+kind)


@pytest.mark.parametrize('ident,length,sha,raw',GOLDENS,ids=[v[0] for v in GOLDENS])
def test_exact_source_arithmetic_and_schema_E01_E20(ident,length,sha,raw):
    assert len(raw.encode())==length
    assert hashlib.sha256(raw.encode()).hexdigest()==sha
    if ident=='V030':
        with pytest.raises(ContractError,match='Input format'):
            Record(raw.encode())
    else:
        r=Record(raw.encode()); validate_record(r,vector_records())
        assert r.encoded==canonical_bytes(json.loads(raw))


def test_corrected_v030_positive_and_historical_negative():
    r=Record(CORRECTED.encode());validate_record(r,vector_records())
    assert r.digest=='1ee3123931b2fdac839858cc79d20bd05342c778c2855fb2cef3a26c7bf4fe58'
    assert r.value['required_action']=='RELOAD'
    assert {r.value['kind'] for r in vector_records().values()}==set(SCHEMAS)


@pytest.mark.parametrize('kind',list(SCHEMAS))
def test_E01_E02_closed_fields_and_null_not_absent(kind):
    r=next(r for r in vector_records().values() if r.value['kind']==kind)
    for key in r.value:
        bad=r.value;bad.pop(key)
        with pytest.raises(ContractError):validate_shape(bad)
    bad=r.value;bad['extra']=None
    with pytest.raises(ContractError):validate_shape(bad)


def test_E03_unicode_no_normalization_and_exact_escaping():
    assert canonical_bytes({'a':'é'})!=canonical_bytes({'a':'e\u0301'})
    assert canonical_bytes({'a':'Рынок 🎞/\n'})==b'{"a": "'+ 'Рынок 🎞'.encode()+b'/\\n"}'
    for bad in ('\ud800','\udfff'):
        with pytest.raises(ContractError):canonical_bytes({'a':bad})


@pytest.mark.parametrize('bad',[True,1.0,-1,MAX_INT+1,'1'])
def test_E04_E05_integer_types(bad):
    value=record('BatchPermit').value;value['valid_from_tick']=bad
    with pytest.raises(ContractError):validate_shape(value)


def test_E04_maximum_is_not_rounded():
    assert canonical_bytes({'n':MAX_INT})==b'{"n": 9223372036854775807}'


@pytest.mark.parametrize('raw',[b'{"x":1,"x":2}',b'\xef\xbb\xbf{}',b'{"x":NaN}',b'{"x":Infinity}',b'{"x":1.0}',b'\xff'])
def test_E05_decode_rejects_ambiguous_or_invalid_wire(raw):
    with pytest.raises(ContractError):decode(raw)


def test_E06_wrong_reference_type_missing_closure_and_mutable_copy():
    r=record('FixtureRegistry');bad=r.value;bad['fixtures'][0]['kind']='PURE.BatchPermit'
    with pytest.raises(ContractError):validate_shape(bad)
    with pytest.raises(ContractError):validate_record(r,{})
    value=r.value;value['fixtures'].clear();assert r.value['fixtures']


def test_E20_error_shape_rejects_alias_and_unknown_action():
    from experimental_mvp.offline_execution.contracts import response_error
    e=response_error('STALE_WORKER_FENCE','SUBMIT');assert e['required_action']=='RELOAD'
    e['effect']=e.pop('external_effect')
    with pytest.raises(ContractError):validate_shape(e)


def test_unknown_version_scope_and_record_kind_fail_closed():
    r=record('FixtureDescriptor').value
    for field,value,code in [('version',2,'VERSION_UNSUPPORTED'),('scope','PRODUCTION','PROFILE_UNQUALIFIED'),('kind','PG.RenderAuthorization','OPERATION_NOT_AVAILABLE')]:
        bad=dict(r);bad[field]=value
        with pytest.raises(ContractError) as e:validate_shape(bad)
        assert e.value.code==code


def independent_encode(value):
    """Second arithmetic oracle: no json encoder; integers never become floats."""
    if value is None:return b'null'
    if type(value) is bool:return b'true' if value else b'false'
    if type(value) is int:return str(value).encode('ascii')
    if type(value) is str:
        escapes={'"':'\\"','\\':'\\\\','\b':'\\b','\f':'\\f','\n':'\\n','\r':'\\r','\t':'\\t'}
        return ('"'+''.join(escapes.get(c,('\\u%04x'%ord(c)) if ord(c)<32 else c) for c in value)+'"').encode('utf-8')
    if type(value) is list:return b'['+b', '.join(independent_encode(x) for x in value)+b']'
    if type(value) is dict:return b'{'+b', '.join(independent_encode(k)+b': '+independent_encode(value[k]) for k in sorted(value))+b'}'
    raise AssertionError('Oracle supports contract JSON values only')


@pytest.mark.parametrize('ident,length,sha,raw',GOLDENS,ids=[v[0] for v in GOLDENS])
def test_E04_independent_codec_matches_fixed_bytes(ident,length,sha,raw):
    assert independent_encode(json.loads(raw))==raw.encode()
    assert independent_encode({'n':MAX_INT})==b'{"n": 9223372036854775807}'


def test_atomic_write_set_rejects_unrelated_extra_member():
    ws=record('AtomicWriteSet').value
    ws['members'].append(record('FixtureDescriptor').ref)
    ws['members'].sort(key=lambda x:(x['kind'],x['digest']))
    ws={k:v for k,v in ws.items() if k not in ('kind','version','scope')}
    bad=seal('AtomicWriteSet',**ws)
    with pytest.raises(ContractError) as exc:validate_record(bad,vector_records())
    assert exc.value.code=='STORE_CORRUPT'
